      out.append({'career_node_id':i,'career_node_slug':slug,'career_breadcrumb':bread,'relation':rel,'confidence':conf,'mapping_status':status})
    return out

def mappings(course,branch):
    c=course.lower(); b=branch.lower()
    # engineering
    if c.startswith('m.tech'):
      if 'civil' in b: return m([84],{84:('closest-specialization','medium','reviewed_against_local_tree')})
